import textwrap
from .managedobject import ManagedObject
from taf.internal.core import camel_case
from typing import Any, Type

class MISSING(object):
    pass

def _instantiate(attr_name, default_value, is_property):
    # Validate input parameters
    assert isinstance(attr_name, str) and attr_name.isidentifier(), f"attr_name is not an identifier: {attr_name!r}"
    assert isinstance(is_property, bool), f"is_property is not a boolean: {is_property!r}"

    # Generate class name
    class_name = f"Using{camel_case(attr_name)}"

    # Generate class template
    if default_value is MISSING:
        parameter = attr_name
        attribute = f"self._{attr_name} = {attr_name}"
    else:
        parameter = f"{attr_name}=MISSING"
        attribute = f"self._{attr_name} = {default_value!r} if {attr_name} is MISSING else {attr_name}"
    attribute_template = f"""
class {class_name}(object):
    def __init__(self, {parameter}, **kwargs):
        super({class_name}, self).__init__(**kwargs)
        {attribute}
        if isinstance({attr_name}, ManagedObject) and isinstance(self, ManagedObject):
            self.add_prerequisite({attr_name})
    """
    if is_property:
        attribute_template += f"""
    @property
    def {attr_name}(self):
        return self._{attr_name}
    """

    # Execute the generated class
    globals_ = {"ManagedObject": ManagedObject, "MISSING": MISSING}
    exec(textwrap.dedent(attribute_template), globals_)
    return globals_[class_name]


_classes = {}


def Using(attr_name: str, default_value: Any = MISSING, is_property: bool = True) -> Type[object]:
    """
    Create a mix-in class, which adds an instance attribute with a given name, that gets its value from a constructor
    parameter. The constructor parameter can optionally have a default value and optionally be accessible as a property.
    If the argument value is a ManagedObject and the mixing-in class too, then the former becomes a prerequisite of the
    latter.

    Usage:

        for adding mandatory parameter 'tool_executor' as attribute 'self._tool_executor' and as it is ManagedObject
        type adding it as prerequisite:

            Using('tool_executor')

        for adding optional parameter 'collector' as attribute 'self._collector' and as it is ManagedObject type adding
        it as prerequisite if provided:

            Using('collector', default_value=None)

        for adding optional parameter 'setup_command' with default value tuple() as attribute 'self._setup_command':

            Using('setup_commands', default_value=tuple())

    """
    class_key = (attr_name, default_value, is_property)
    if class_key not in _classes:
        _classes[class_key] = _instantiate(attr_name=attr_name,
                                           default_value=default_value,
                                           is_property=is_property)
    return _classes[class_key]
